insert into public.cards(id, rarity, name, orientation, width, height, event_id, tier, effect, color_a, color_b, storage_path, thumb_path, active, sort)
select 'b2-' || rar || '-' || lpad(n::text, 3, '0'), rar, vn || ' #' || lpad((st + n - 1)::text, 3, '0'),
       case when w > h * 1.05 then 'landscape' else 'portrait' end, w, h, null, null, null, null, null,
       'b2/' || rar || '/b2-' || rar || '-' || lpad(n::text, 3, '0') || '.webp',
       'thumbs/b2-' || rar || '-' || lpad(n::text, 3, '0') || '.webp', false, st + n - 1
from d, unnest(dims) with ordinality as x(wh, n),
     lateral (select split_part(wh, 'x', 1)::int as w, split_part(wh, 'x', 2)::int as h) s
on conflict (id) do nothing;

